"""Trace designated regression cases without affecting candidate selection."""
def cases(audit,rows,cache,borrow_targets,intraday_targets,research,now):
    records={s['ticker']:(s,a) for s,a in rows};borrow={s['ticker'] for s in borrow_targets};intra={s['ticker'] for s in intraday_targets};rank={s['ticker']:i+1 for i,(s,a) in enumerate(research)}
    output=[]
    for ticker in ('SHFS','NCPL'):
        entry=audit.get(ticker,{});stock,analysis=records.get(ticker,({},{}));obs=cache.get(ticker,{});b=obs.get('borrow',{});si=obs.get('short_interest',{})
        output.append({'ticker':ticker,'name':entry.get('name',obs.get('name')),'observed_at':now.isoformat(),'listed':entry.get('listed',False),'scope_reason':entry.get('scope_reason'),'daily_received':entry.get('daily_received',False),'price_as_of':entry.get('price_as_of'),'borrow_attempted':ticker in borrow,'borrow_source':b.get('source'),'borrow_as_of':b.get('as_of'),'borrow_observed_at':b.get('observed_at'),'ctb':b.get('ctb'),'available':b.get('available'),'official_interest_valid':analysis.get('official_interest',{}).get('scoring_valid'),'official_interest_source':si.get('source'),'official_interest_observed_at':si.get('observed_at'),'dollar_ratio':analysis.get('market',{}).get('dollar_ratio'),'market_as_of':analysis.get('market',{}).get('as_of'),'intraday_attempted':ticker in intra,'intraday_as_of':analysis.get('intraday',{}).get('as_of'),'score':analysis.get('observed_score'),'coverage':analysis.get('coverage'),'stage':analysis.get('stage'),'candidate':analysis.get('candidate',False),'candidate_type':analysis.get('candidate_type'),'early_signal':analysis.get('early_signal'),'research_rank':rank.get(ticker),'top10_reason':entry.get('scope_reason') or ('연구 TOP10' if ticker in rank else '관측 점수 순위 또는 정지·후보 요건 미충족'),'historical_verdict':'검증 불가: 당시 확보된 시점별 CTB·전체 시세·계약 스냅샷 없이 조기 포착을 소급 주장하지 않음'})
    return output
